VALUES (104, '6005', '자유게시판', '가입인사 드려요!!', '2026-09-18 15:35:00', 8, NULL, NULL, NULL, NULL, NULL, NULL, '가입인사 드립니다.\n\n부실차주 준비하고 있습니다.\n\n잘 부탁드립니다.\n\n[댓글 2개]\n- 전자책과 단톡방 정보를 이메일로 발송하였습니다. 감사합니다.\n- 가입 축하드립니다', NULL, NULL, NULL, NULL, 'https://cafe.naver.com/ArticleRead.nhn?clubid=31312978&articleid=6005&referrerAllArticles=true', '2026-09-19 22:45:00', 'lib-import-20261003', 'lib-import-20261003', '2026-09-26 03:14:28.296233', '2026-09-26 03:14:28.296238');
