VALUES (102, '6003', '자유게시판', '가입했어요~~', '2026-09-18 14:27:00', 4, NULL, NULL, NULL, NULL, NULL, NULL, '회생중인데 부실차주로 갈아탈수있을까해서 가입했어요!!\n\n[댓글 1개]\n- 가입 축하해요', NULL, NULL, NULL, NULL, 'https://cafe.naver.com/ArticleRead.nhn?clubid=31312978&articleid=6003&referrerAllArticles=true', '2026-09-19 22:45:00', 'lib-import-20261003', 'lib-import-20261003', '2026-09-26 03:14:28.277714', '2026-09-26 03:14:28.277719');
